// Giltiga aktiveringskoder, med lag-etikett för välkomstrutan och valfritt utgångsdatum
// (t.ex. "2026-12-31" — kör till och med det datumet). Lägg till/ta bort koder här vid behov.
const VALID_CODES = {
  "HUFF-ADMIN-9K2X": { label: null, expires: null },
  "HUFF-TRANARE-BPXE": { label: null, expires: null },
  "HUFF-P6-WAJH": { label: "HuFF P6", expires: null },
  "HUFF-P7-ZX6C": { label: "HuFF P7", expires: null },
  "HUFF-P8-PAGS": { label: "HuFF P8", expires: null },
  "HUFF-P9-AGWT": { label: "HuFF P9", expires: null },
  "HUFF-P10-HU3A": { label: "HuFF P10", expires: null },
};

// Sant om koden har ett utgångsdatum som har passerat (jämfört med dagens datum).
function isCodeExpired(entry) {
  if (!entry || !entry.expires) return false;
  const expiry = new Date(entry.expires + "T23:59:59");
  return new Date() > expiry;
}

